import { Component } from '@angular/core';
import { Router } from '@angular/router';
import { AuthService } from '../../services/auth.service';

@Component({
  selector: 'app-register',
  templateUrl: './register.component.html',
  styleUrls: ['./register.component.css']
})
export class RegisterComponent {
  username = '';
  email = '';
  password = '';
  loading = false;
  errorMessage = '';

  constructor(private auth: AuthService, private router: Router) {}

  async handleRegister(): Promise<void> {
    this.loading = true;
    this.errorMessage = '';
    await this.auth.register({ username: this.username, email: this.email, password: this.password });
    this.loading = false;
  }

  goToLogin(): void {
    this.router.navigate(['/login']);
  }
}
<div class="min-h-screen bg-gradient-to-br from-indigo-50 to-purple-50 flex items-center justify-center">
  <div class="bg-white p-8 rounded-2xl shadow-lg w-full max-w-md border border-gray-100">
    <div class="text-center mb-8">
      <div class="w-12 h-12 bg-primary rounded-lg flex items-center justify-center mx-auto mb-4">
        <svg class="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v3h8z" />
        </svg>
      </div>
      <h1 class="text-2xl font-bold text-gray-900 mb-2">Otuya Global Digital Solution</h1>
      <p class="text-gray-500">Create your account</p>
    </div>

    <div *ngIf="errorMessage" class="mb-6 p-3 bg-red-50 border border-red-100 rounded-md text-sm text-red-700">
      {{ errorMessage }}
    </div>

    <form (ngSubmit)="handleRegister()" class="space-y-4">
      <div>
        <label class="block text-sm font-medium text-gray-700 mb-1">Username</label>
        <input [(ngModel)]="username" name="username" type="text" placeholder="e.g., john_doe"
          class="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-primary focus:border-transparent outline-none transition-all" />
      </div>

      <div>
        <label class="block text-sm font-medium text-gray-700 mb-1">Email</label>
        <input [(ngModel)]="email" name="email" type="email" placeholder="john@example.com"
          class="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-primary focus:border-transparent outline-none transition-all" />
      </div>

      <div>
        <label class="block text-sm font-medium text-gray-700 mb-1">Password</label>
        <input [(ngModel)]="password" name="password" type="password" placeholder="••••••••"
          class="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-primary focus:border-transparent outline-none transition-all" />
      </div>

      <button type="submit" [disabled]="loading"
        class="w-full bg-primary text-white px-4 py-2 rounded-lg font-semibold hover:bg-primary-dark transition-colors disabled:opacity-60">
        {{ loading ? 'Creating account...' : 'Create Account' }}
      </button>
    </form>

    <div class="mt-6 pt-6 border-t border-gray-100 text-center">
      <p class="text-sm text-gray-600">Already have an account? <button type="button" (click)="goToLogin()" class="text-primary hover:text-primary-dark font-medium">Sign in</button></p>
    </div>
  </div>
</div>
